import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps
import xml.etree.ElementTree as ET
import logging

app = Flask(__name__)
app.config['DATABASE'] = '/var/app/data/inventory.db'
app.config['UPLOAD_DIR'] = '/var/app/uploads'

logger = logging.getLogger('inventory_service')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        db = get_db()
        row = db.execute('SELECT id FROM api_clients WHERE key_hash = ?',
                        (hashlib.sha256(api_key.encode()).hexdigest(),)).fetchone()
        if not row:
            return jsonify({'error': 'Invalid API key'}), 403
        g.client_id = row['id']
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v2/inventory/import', methods=['POST'])
@require_api_key
def import_inventory():
    """Import inventory data from XML payload.
    Supports standard inventory XML schema with item elements.
    """
    content_type = request.content_type or ''
    if 'xml' not in content_type.lower():
        return jsonify({'error': 'Content-Type must be application/xml'}), 415

    raw_xml = request.get_data(as_text=True)
    if not raw_xml or len(raw_xml) > 524288:  # 512KB limit
        return jsonify({'error': 'Invalid payload size'}), 400

    try:
        # Parse the XML inventory document
        root = ET.fromstring(raw_xml)
    except ET.ParseError as e:
        logger.warning(f"XML parse error from client {g.client_id}: {e}")
        return jsonify({'error': 'Malformed XML'}), 400

    items_imported = 0
    errors = []
    db = get_db()

    for item in root.findall('.//item'):
        sku = item.findtext('sku', '').strip()
        name = item.findtext('name', '').strip()
        qty_text = item.findtext('quantity', '0').strip()
        location = item.findtext('warehouse_location', '').strip()

        if not sku or not name:
            errors.append(f"Missing sku/name in item")
            continue

        try:
            quantity = int(qty_text)
        except ValueError:
            errors.append(f"Invalid quantity for SKU {sku}")
            continue

        db.execute(
            'INSERT OR REPLACE INTO inventory (sku, name, quantity, location, client_id) VALUES (?, ?, ?, ?, ?)',
            (sku, name, quantity, location, g.client_id)
        )
        items_imported += 1

    db.commit()
    return jsonify({
        'imported': items_imported,
        'errors': errors,
        'client_id': g.client_id
    })

@app.route('/api/v2/inventory/export', methods=['GET'])
@require_api_key
def export_inventory():
    """Export inventory as JSON for the authenticated client."""
    db = get_db()
    rows = db.execute(
        'SELECT sku, name, quantity, location FROM inventory WHERE client_id = ?',
        (g.client_id,)
    ).fetchall()
    return jsonify({'items': [dict(r) for r in rows]})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
